fn solve(a: i8, b: i8, c: i8) -> i8 {
    let max_value = a.max(b).max(c);
    
    // Calculate how much each number needs to reach the maximum
    let diff_a = max_value - a;
    let diff_b = max_value - b;
    let diff_c = max_value - c;

    // Total operations needed
    let total_diff = diff_a + diff_b + diff_c;

    // Each operation can increase two numbers by 1 or one number by 2
    // We can use the formula: operations = (total_diff + 1) / 2
    // This works because:
    // - If total_diff is even, we can perfectly pair them.
    // - If total_diff is odd, we will need one extra operation.
    (total_diff + 1) / 2
}